import type { Neighbour } from './types';

/** These strings are what the server verifies signatures against. Keep byte-identical to backend/app/services/crypto.py;
 *  docs/test-vectors.json (generated by the server code) pins the contract in tests. */
export const registerMessage = (studentId: string, model: string) => `register:${studentId}:${model}`;
export const checkinMessage = (sessionId: string, nonce: string) => `checkin:${sessionId}:${nonce}`;

export function reportMessage(sessionId: string, studentId: string, neighbours: Neighbour[]): string {
  // Python: sorted([peer, int(rssi), int(count)]) lexicographically, json.dumps(separators=(",", ":"))
  const rows = neighbours
    .map((n) => [n.peer_id, Math.trunc(n.rssi_median), Math.trunc(n.sample_count)] as [string, number, number])
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] - b[1] || a[2] - b[2]));
  return `report:${sessionId}:${studentId}:${JSON.stringify(rows)}`;
}
